const projects = `<main class="projects-main wrap"><section class="projects-heading"><div class="eyebrow"><span class="status-dot"></span> CONSTRUCTION × TECHNOLOGY</div><h1>Better tools.<br><em>Better building.</em><span class="green"> </span></h1><div class="projects-subtitle"><p>Exploring digital solutions for the built environment.<br>From connected fieldwork to smarter project delivery.</p><span>03 PROJECTS / 02 CONCEPTS</span></div></section><section aria-label="Project concepts">${projectCards}<p class="content-note">Explore the project titles or buttons for details. The additional concept cards are illustrative.</p></section><div class="projects-end"><h2>The next chapter<br>of construction.</h2><a class="text-link" href="./">Back to home ${arrow}</a></div></main>`;
const story = `<main class="story-main wrap"><section class="story-hero"><div class="eyebrow"><span class="status-dot"></span> THE PERSON BEHIND THE WORK</div><h1>About Me<span class="green">.</span></h1><p class="story-lead">It started with building things.<br>It became a search for <em>better ways to build.</em></p><p class="story-intro">I’m Daniel Li. My interest in construction started long before it became my career—with LEGO, sandcastles, and houses made from playing cards. Working alongside my family turned that childhood curiosity into something much bigger.</p></section><div class="story-layout"><aside class="story-photo"><img src="./images/FrontPgaePhoto.jpg" alt="Daniel Li smiling outdoors" width="1381" height="2455"><p>Daniel Li <span>Phoenix, Arizona</span></p><div class="profile-bio"><div class="eyebrow">A LITTLE ABOUT ME</div><p>I was born in Taiwan and raised in Long Beach, California. At 19, I moved to Canada, spending time in Montréal, Québec, and Ottawa, Ontario, to learn French and Mandarin. Finding my way on my own in unfamiliar places taught me to adapt, pick things up quickly, and stay open to learning.</p><p>I’ve traveled to and lived in many countries, and two things always catch my attention: the food and the architecture. I love discovering what a place’s buildings reveal about its history—and what’s worth eating around the corner. When it comes to food, Japan and Taiwan are my favorites.</p><p>My experiences as an international student and an immigrant worker in the U.S. have shaped how I see people and problems. I’ve learned to consider different perspectives, adapt how I communicate, and recognize that every client brings a different background and set of priorities. That outlook is something I bring to my work in construction every day.</p></div></aside><div class="story-chapters"><section class="story-chapter"><div class="eyebrow">01 / CONSTRUCTION</div><h2>From LEGO to real job sites.</h2><p>Growing up around my family’s residential construction business, I was fascinated by everything that went into a home: the finances, the planning, and the building process itself. I got to see how decisions made long before construction began shaped what happened on site.</p><p>Working closely with clients during design and with contractors gave me a view of construction from different perspectives. Later, hands-on work as a field engineer and framing carpenter grounded that understanding in the realities of framing, layout, installation, and reading plans.</p></section><section class="story-chapter"><div class="eyebrow">02 / TECHNOLOGY</div><h2>Seeing what technology could change.</h2><p>The closer I worked with clients and contractors, the more I saw how technology could improve the process. Better tools could help reduce labor costs, automate parts of modeling and quantity takeoff, and make planning more efficient.</p><p>That’s what led me back to college: I wanted to learn how to solve construction problems in more innovative and efficient ways. I studied Virtual Design & Construction and Architectural Technology at Brigham Young University–Idaho, building on my field experience with skills in digital modeling and coordination.</p></section><section class="story-chapter"><div class="eyebrow">03 / BUSINESS INTELLIGENCE</div><h2>Turning information into insight.</h2><p>Today, I’m a VDC Business Intelligence Manager at Origin Design & Technology in Phoenix. I work with operational, financial, and production data from BIM, reality capture, drone operations, and digital construction workflows.</p><p>My focus is on making that information useful through dashboards, reports, standards, and strategies that support project performance and business decisions. I’m also pursuing a master’s degree in Technology Management: Business Analytics at Avila University.</p></section><section class="story-personal"><div class="eyebrow">THE WHY BEHIND THE WORK</div><h2>Better ways to build.</h2><p>Construction is what first drew me in. Technology gave me more ways to approach its challenges. Bringing those two interests together is why I chose this path—and why I keep learning.</p></section></div></div><section class="story-connect"><h2>Let’s connect.</h2><p>Interested in construction, technology, or the space between them?</p><div class="story-socials" aria-label="Social profiles"><a class="social-icon" href="https://www.linkedin.com/in/daniel-li95/" target="_blank" rel="noopener noreferrer" aria-label="Daniel Li on LinkedIn (opens in a new tab)" title="LinkedIn"><svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M20.45 2H3.55C2.69 2 2 2.68 2 3.52v16.96C2 21.32 2.69 22 3.55 22h16.9c.86 0 1.55-.68 1.55-1.52V3.52C22 2.68 21.31 2 20.45 2ZM7.93 18.75H4.98V9.2h2.95v9.55ZM6.46 7.9a1.71 1.71 0 1 1 0-3.42 1.71 1.71 0 0 1 0 3.42Zm12.29 10.85H15.8V14.1c0-1.11-.02-2.54-1.55-2.54-1.55 0-1.79 1.21-1.79 2.46v4.73H9.51V9.2h2.83v1.3h.04c.39-.74 1.36-1.53 2.79-1.53 2.98 0 3.58 1.96 3.58 4.51v5.27Z"/></svg></a><a class="social-icon" href="https://www.instagram.com/danfromorigin/" target="_blank" rel="noopener noreferrer" aria-label="Daniel Li on Instagram (opens in a new tab)" title="Instagram"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none"/></svg></a></div><a class="text-link" href="./">Back to home <span class="link-arrow" aria-hidden="true">↗</span></a></section></main>`;
const scanDetail = `<main class="scan-detail wrap"><nav class="project-breadcrumb" aria-label="Breadcrumb"><a href="./projects.html">Projects</a><span aria-hidden="true">/</span><span aria-current="page">Building &amp; Site Scan</span></nav><section class="scan-detail-heading"><div class="eyebrow"><span class="status-dot"></span> REALITY CAPTURE / PROJECT SPOTLIGHT</div><h1>Building &amp;<br><em>Site Scan.</em></h1><p>Interior and exterior, captured together.<br>Documenting existing conditions for remodeling.</p><div class="tags"><span>Point Cloud</span><span>Existing Conditions</span><span>Reality Capture</span></div></section><figure class="scan-detail-video"><div class="scan-video-player"><iframe src="https://www.youtube-nocookie.com/embed/j8nImC56aK0?autoplay=1&amp;mute=1&amp;playsinline=1&amp;rel=0&amp;controls=0" title="Building &amp; Site Scan — project video" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><figcaption>Building and site point-cloud walkthrough. Plays muted; click or tap the video to pause or resume.</figcaption></figure><div class="scan-detail-body"><aside class="scan-facts" aria-label="Project at a glance"><div class="eyebrow">AT A GLANCE</div><dl><dt>Focus</dt><dd>Reality Capture</dd><dt>Representation</dt><dd>Point Cloud &amp; BIM Model</dd><dt>Capture Tool</dt><dd>VLX 2</dd><dt>Scope</dt><dd>Building Interior, Exterior &amp; Surrounding Site</dd><dt>Purpose</dt><dd>Existing Conditions for Remodeling</dd><dt>Modeling</dt><dd>Revit / Scan to BIM</dd><dt>Rendering</dt><dd>D5 Render</dd><dt>On This Page</dt><dd>Scan Walkthrough, Site Image &amp; D5 Rendering</dd></dl></aside><div class="scan-detail-copy"><section><div class="eyebrow">01 / OVERVIEW</div><h2>One building. Interior and exterior.</h2><p>This project uses a VLX 2 to document existing conditions for a remodeling project. The scan covers the building’s interior and exterior, along with its surrounding site.</p><p>The point cloud provides a spatial record of the building before remodeling, giving the project a reference for understanding existing conditions during planning.</p></section><section><div class="eyebrow">02 / CAPTURE APPROACH</div><h2>Existing conditions, captured with VLX 2.</h2><ul><li><strong>VLX 2 scanning:</strong> captures the existing building and surrounding site as a point cloud.</li><li><strong>Interior and exterior coverage:</strong> documents conditions inside and outside the building.</li><li><strong>Remodeling reference:</strong> provides a spatial record to support understanding existing conditions during planning.</li></ul></section></div></div><section class="scan-supplement" aria-labelledby="scan-image-title"><div class="eyebrow">03 / ANOTHER PERSPECTIVE</div><h2 id="scan-image-title">A top-down view of existing conditions.</h2><p class="scan-supplement-intro">An additional view of the office headquarters scan, showing the building footprint and its surrounding site.</p><figure class="scan-detail-image"><div class="scan-detail-display"><img src="./images/New%20Office%20Headquater.png" alt="Top-down scan view of the office headquarters building, surrounding parking areas, and landscaping" width="1264" height="1322" loading="lazy" draggable="false"></div><figcaption>Office headquarters — top-down scan view.</figcaption></figure></section><section class="scan-supplement scan-bim-rendering" aria-labelledby="bim-render-title"><div class="eyebrow">04 / SCAN TO BIM</div><h2 id="bim-render-title">From captured conditions to a rendered model.</h2><p class="scan-supplement-intro">The scan was used as a reference to model the building in Revit through a scan-to-BIM workflow. This D5 rendering video presents the resulting model, connecting the captured existing conditions with a visualized BIM representation.</p><figure class="scan-detail-video"><div class="scan-video-player"><iframe src="https://www.youtube-nocookie.com/embed/OI3zFzO1qmk?autoplay=1&amp;mute=1&amp;playsinline=1&amp;rel=0&amp;controls=0" title="Office headquarters — D5 rendering of the Revit scan-to-BIM model" loading="lazy" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><figcaption>Scan to BIM in Revit · Rendered in D5. Plays muted; click or tap the video to pause or resume.</figcaption></figure></section><div class="scan-detail-end"><a class="button primary" href="./projects.html">Back to projects <span class="link-arrow" aria-hidden="true">↗</span></a><a class="text-link" href="./">Home <span class="link-arrow" aria-hidden="true">↗</span></a></div></main>`;
const trafficDetail = `<main class="scan-detail wrap"><nav class="project-breadcrumb" aria-label="Breadcrumb"><a href="./projects.html">Projects</a><span aria-hidden="true">/</span><span aria-current="page">Project Rendering &amp; Proposal</span></nav><section class="scan-detail-heading"><div class="eyebrow"><span class="status-dot"></span> CONSTRUCTION VISUALIZATION / PROJECT SPOTLIGHT</div><h1>Project Rendering<br><em>&amp; Proposal.</em></h1><p>Visualizing roadwork and traffic control<br>through different phases of construction.</p><div class="tags"><span>Construction Phasing</span><span>Traffic Control</span><span>Lumion Rendering</span></div></section><figure class="scan-detail-video"><div class="scan-video-player"><iframe src="https://www.youtube-nocookie.com/embed/P_0hqkJ4qEQ?autoplay=1&amp;mute=1&amp;playsinline=1&amp;rel=0&amp;controls=0" title="Project Rendering &amp; Proposal — construction traffic phasing video" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><figcaption>Roadwork and traffic-control phasing visualization. Plays muted; click or tap the video to pause or resume.</figcaption></figure><div class="scan-detail-body"><aside class="scan-facts" aria-label="Project at a glance"><div class="eyebrow">AT A GLANCE</div><dl><dt>Focus</dt><dd>Roadwork Phasing &amp; Traffic Control</dd><dt>Modeling</dt><dd>SketchUp</dd><dt>Rendering</dt><dd>Lumion</dd><dt>Video Editing</dt><dd>DaVinci Resolve</dd></dl></aside><div class="scan-detail-copy"><section><div class="eyebrow">01 / OVERVIEW</div><h2>Making the construction plan visible.</h2><p>This project uses a modeled roadwork scenario to show traffic control during different phases of construction. The rendering presents the work area alongside vehicles and the surrounding streetscape, helping communicate the proposed construction sequence.</p><p>The scene was modeled in SketchUp and rendered in Lumion, with DaVinci Resolve used for video editing.</p></section><section><div class="eyebrow">02 / A CLOSER LOOK</div><h2>Communicating each phase.</h2><ul><li><strong>Construction phasing:</strong> visualizing roadwork across different stages of the project.</li><li><strong>Traffic control:</strong> showing how traffic is managed around the construction area during each phase.</li><li><strong>Project presentation:</strong> combining SketchUp modeling, Lumion rendering, and DaVinci Resolve video editing to communicate the proposal.</li></ul></section></div></div><div class="scan-detail-end"><a class="button primary" href="./projects.html">Back to projects <span class="link-arrow" aria-hidden="true">↗</span></a><a class="text-link" href="./">Home <span class="link-arrow" aria-hidden="true">↗</span></a></div></main>`;
const inlDetail = `<main class="scan-detail wrap"><nav class="project-breadcrumb" aria-label="Breadcrumb"><a href="./projects.html">Projects</a><span aria-hidden="true">/</span><span aria-current="page">INL Building Concept</span></nav><section class="scan-detail-heading"><div class="eyebrow"><span class="status-dot"></span> ACADEMIC TEAM PROJECT / COMMERCIAL DESIGN</div><h1>INL Building<br><em>Concept.</em></h1><p>A distinctive building concept.<br>Designed with sustainability and daylight in mind.</p><div class="tags"><span>Commercial Building</span><span>Sustainability</span><span>Daylighting</span></div></section><section class="model-project" aria-labelledby="model-title"><div class="section-heading"><div><div class="eyebrow">EXPLORE THE DESIGN</div><h2 id="model-title">An idea in three dimensions<span class="blue">.</span></h2></div></div><div class="model-viewer"><div class="model-stage"><canvas tabindex="0" aria-label="Interactive INL building concept. Drag to rotate, scroll or pinch to zoom, right-drag or use two fingers to pan. Arrow keys pan."></canvas><p class="model-status" role="status">Loading 3D model…</p><span class="model-view-label" aria-hidden="true">DL / CONCEPT MODEL</span></div><div class="model-toolbar" role="group" aria-label="3D model controls"><button type="button" data-action="zoom-in" disabled aria-label="Zoom in">+</button><button type="button" data-action="zoom-out" disabled aria-label="Zoom out">−</button><button type="button" data-action="reset" disabled>Reset view</button><button type="button" data-action="fullscreen" disabled>Fullscreen</button></div><p class="model-help">Drag to rotate · Scroll or pinch to zoom · Right-drag or two fingers to pan</p></div><p class="content-note">Presentation materials based on the Revit reference: glazed walls, steel-colored panel outlines, gray roofs, and a grass courtyard.</p></section><div class="scan-detail-body"><aside class="scan-facts" aria-label="Project at a glance"><div class="eyebrow">AT A GLANCE</div><dl><dt>Project Type</dt><dd>Academic Team Design</dd><dt>Brief</dt><dd>Commercial Building for INL</dd><dt>Design Goals</dt><dd>Unique Architecture, Sustainability &amp; Daylight</dd><dt>Concept Features</dt><dd>Garden Break Space, Rooftop Solar &amp; Covered Parking</dd><dt>Modeling Software</dt><dd>Revit &amp; SketchUp</dd><dt>Rendering Software</dt><dd>Twinmotion</dd><dt>Stage</dt><dd>Design Concept</dd></dl></aside><div class="scan-detail-copy"><section><div class="eyebrow">01 / THE BRIEF</div><h2>A building with a different perspective.</h2><p>For this school project, our team was asked to design a commercial building for INL that would be distinctive, green, and filled with natural sunlight. This model presents the concept we developed in response to that brief.</p><p>We used Revit and SketchUp for modeling, with Twinmotion for the architectural renderings and interior visualizations.</p></section><section><div class="eyebrow">02 / DESIGN INTENT</div><h2>Form, light, and sustainability.</h2><ul><li><strong>Distinctive architecture:</strong> explore a building concept with its own visual identity.</li><li><strong>Natural daylight:</strong> make bringing sunlight into the building a central design goal, with glazed walls and steel framing.</li><li><strong>Garden break space:</strong> offer a planted outdoor setting where people can step away from work and recharge.</li><li><strong>Rooftop solar:</strong> include solar panels as part of the concept’s renewable-energy strategy.</li><li><strong>Covered parking:</strong> provide shade and extend comfort considerations beyond the building itself.</li></ul><p>This is an academic concept. These are design intentions, rather than measured daylight or energy-performance results.</p></section></div></div><section class="inl-gallery-group"><div class="eyebrow">03 / CONCEPT &amp; EXTERIOR</div><h2>From the first idea to the building.</h2><div class="inl-gallery-grid"><figure class="inl-gallery-figure"><img src="./images/inl/building-front.webp" alt="Rendered front view of the INL concept with glazed walls and planted terraces" width="1920" height="1080" loading="lazy" draggable="false"><figcaption><h3>Building exterior</h3><p>A glazed exterior and stepped building form connect the indoor spaces with the garden and surrounding site.</p></figcaption></figure><figure class="inl-gallery-figure"><img src="./images/inl/concept-model.webp" alt="Concept model showing the stepped building form and central open space" width="1562" height="852" loading="lazy" draggable="false"><figcaption><h3>The starting concept</h3><p>The concept model explores a stepped building form around a central open space, with daylight and a distinctive identity guiding the design.</p></figcaption></figure></div></section><section class="inl-gallery-group"><div class="eyebrow">04 / SUSTAINABILITY &amp; WELLBEING</div><h2>A greener place to work and recharge.</h2><div class="inl-gallery-grid"><figure class="inl-gallery-figure inl-gallery-wide"><img src="./images/inl/rooftop-garden.webp" alt="Grass and trees in the rooftop garden with surrounding glazed building spaces" width="1920" height="1080" loading="lazy" draggable="false"><figcaption><h3>A garden for a change of pace</h3><p>The garden offers a green place to step away from work, take a break, and reconnect with the outdoors. Planting and open space bring a different rhythm to the workplace.</p></figcaption></figure><figure class="inl-gallery-figure"><img src="./images/inl/rooftop-solar.webp" alt="Rendering of solar panels arranged across the building roof" width="1920" height="1080" loading="lazy" draggable="false"><figcaption><h3>Putting the roof to work</h3><p>Rooftop solar panels form part of the proposal’s renewable-energy strategy, using roof space as an opportunity for on-site generation.</p></figcaption></figure><figure class="inl-gallery-figure"><img src="./images/inl/covered-parking.webp" alt="Parking canopies shading vehicles beside landscaped pedestrian areas" width="1920" height="1080" loading="lazy" draggable="false"><figcaption><h3>Shade beyond the building</h3><p>Covered parking gives vehicles and people relief from direct sun, extending the sustainability and comfort goals into the surrounding site.</p></figcaption></figure></div></section><section class="inl-gallery-group"><div class="eyebrow">05 / INTERIOR SPACES</div><h2>Daylight, work, and places to pause.</h2><div class="inl-gallery-grid"><figure class="inl-gallery-figure inl-gallery-wide"><img src="./images/inl/breakroom.webp" alt="Sunlit breakroom with tables and chairs beside large windows looking toward the garden" width="1920" height="1080" loading="lazy" draggable="false"><figcaption><h3>A brighter place to pause</h3><p>The breakroom pairs shared seating with generous glazing and views toward the garden, giving people a place to gather away from their desks.</p></figcaption></figure><figure class="inl-gallery-figure"><img src="./images/inl/interior-workspace.webp" alt="Interior rendering showing open workstations, lounge seating, and perimeter glazing" width="1920" height="1080" loading="lazy" draggable="false"><figcaption><h3>Work and shared space together</h3><p>Open workstations and informal seating sit alongside the glazed perimeter, keeping daylight and shared spaces part of the interior experience.</p></figcaption></figure><figure class="inl-gallery-figure"><img src="./images/inl/interior-lounge.webp" alt="Interior lounge with sofas, a staircase, and sunlight through large glazed walls" width="1920" height="1080" loading="lazy" draggable="false"><figcaption><h3>Space for informal connection</h3><p>A lounge beside the stair creates a setting for conversation and short breaks, with daylight reaching the seating through the curtain wall.</p></figcaption></figure></div></section><div class="scan-detail-end"><a class="button primary" href="./projects.html">Back to projects ${arrow}</a><a class="text-link" href="./">Home ${arrow}</a></div></main>`;
document.querySelector('#app').innerHTML = header + (inlPage ? inlDetail : trafficPage ? trafficDetail : scanPage ? scanDetail : storyPage ? story : projectsPage ? projects : home) + footer;

// Reveal page sections once; content stays visible without observer support.
const motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
if (!motionPreference.matches && 'IntersectionObserver' in window) {
  const candidates = [...document.querySelectorAll(
    'main section, .project-card, .career-row, #experience .section-heading, .selected > .section-heading, .story-photo, .scan-facts, main > figure, .scan-detail-end, footer'
  )];
  // Animate the content within large sections instead of hiding their entire container.
  const revealItems = candidates.filter(item => !candidates.some(other => other !== item && item.contains(other)));
  const reveal = target => {
    target.classList.add('scroll-visible');
    observer.unobserve(target);
  };
  const observer = new IntersectionObserver(entries => {
    entries.forEach(({ isIntersecting, target }) => {
      if (isIntersecting) reveal(target);
    });
  }, { threshold: 0, rootMargin: '0px 0px -24px 0px' });
  revealItems.forEach(item => {
    item.classList.add('scroll-reveal');
    observer.observe(item);
  });
  // Keyboard navigation and anchor links should never land on hidden content.
  document.addEventListener('focusin', event => {
    const target = event.target.closest('.scroll-reveal');
    if (target) reveal(target);
  });
  motionPreference.addEventListener('change', ({ matches }) => {
    if (matches) {
      observer.disconnect();
      revealItems.forEach(item => item.classList.add('scroll-visible'));
    }
  });
}

// Keep labels facing the reader while their positions rotate in a sphere.
const cloud = document.querySelector('.skill-cloud');
if (cloud) {
  const coreTools = new Set(['Revit', 'Navisworks', 'Forma', 'eVolve', 'SysQue', 'AutoCAD', 'Bluebeam']);
  const labels = [...cloud.querySelectorAll('.cloud-word')];
  const primary = labels.filter(word => coreTools.has(word.textContent));
  const supporting = labels.filter(word => !coreTools.has(word.textContent));
  primary.forEach(word => word.classList.add('cloud-word-primary'));
  // Spread core tools around the sphere rather than grouping them at one pole.
  const words = [];
  supporting.forEach((word, index) => {
    if (index % 3 === 0 && primary.length) words.push(primary.shift());
    words.push(word);
  });
  words.push(...primary);
  const toggle = document.querySelector('.cloud-toggle');
  let angle = 0;
  let paused = false;
  let inView = false;
  let frame = null;
  let previous = null;
  const positions = words.map((_, index) => {
    const y = 1 - (index / (words.length - 1)) * 2;
    const radius = Math.sqrt(1 - y * y);
    const theta = index * Math.PI * (3 - Math.sqrt(5));
    return { x: Math.cos(theta) * radius, y, z: Math.sin(theta) * radius };
  });
  function render() {
    const radiusX = Math.max(65, cloud.clientWidth / 2 - 80);
    const radiusY = cloud.clientHeight / 2 - 36;
    words.forEach((word, index) => {
      const point = positions[index];
      const x = point.x * Math.cos(angle) - point.z * Math.sin(angle);
      const z = point.x * Math.sin(angle) + point.z * Math.cos(angle);
      const depth = (z + 1) / 2;
      word.style.transform = `translate(-50%, -50%) translate(${x * radiusX}px, ${point.y * radiusY}px) scale(${word.classList.contains('cloud-word-primary') ? 0.95 + depth * 0.2 : 0.68 + depth * 0.28})`;
      word.style.opacity = `${word.classList.contains('cloud-word-primary') ? 0.82 + depth * 0.18 : 0.3 + depth * 0.4}`;
      word.style.zIndex = `${Math.round(depth * 100) + (word.classList.contains('cloud-word-primary') ? 100 : 0)}`;
    });
  }
  function animate(now) {
    if (previous !== null) angle += Math.min(now - previous, 50) * 0.00012;
    previous = now;
    render();
    frame = requestAnimationFrame(animate);
  }
  function updateMotion() {
    if (frame !== null) cancelAnimationFrame(frame);
    frame = null;
    previous = null;
    toggle.hidden = motionPreference.matches;
    if (!paused && !motionPreference.matches && inView && !document.hidden) frame = requestAnimationFrame(animate);
  }
  toggle.addEventListener('click', () => {
    paused = !paused;
    toggle.setAttribute('aria-pressed', `${paused}`);
    toggle.textContent = paused ? 'Resume motion' : 'Pause motion';
    updateMotion();
  });
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(([entry]) => { inView = entry.isIntersecting; updateMotion(); }).observe(cloud);
  } else { inView = true; }
  window.addEventListener('resize', render);
  document.addEventListener('visibilitychange', updateMotion);
  motionPreference.addEventListener('change', updateMotion);
  render();
  updateMotion();
}

if (inlPage) {
  import('./model-viewer.js').then(({ initModelViewer }) => initModelViewer()).catch(() => {
    document.querySelector('.model-status').textContent = 'The viewer couldn’t load. Please refresh to try again.';
  });
}
